import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def F(inp):
    H,W=len(inp),len(inp[0])
    zrows=[r for r in range(H) if sum(1 for v in inp[r] if v!=0)<W*0.9-2]
    barcols=[c for c in range(W) if len({inp[r][c] for r in zrows})==1 and inp[zrows[0]][c]!=0]
    gbarv=[inp[zrows[0]][c] for c in barcols]
    bands=[]
    for r in range(H):
        nz={v for v in inp[r] if v!=0}-set(gbarv)
        if len(nz)==1: bands.append((nz.pop(),r))
    bands.sort(key=lambda b:b[1])
    nbs=len(barcols)
    def zrow(): return [0 if j%2==0 else gbarv[j//2] for j in range(2*nbs+1)]
    def brow(bc): return [bc if j%2==0 else gbarv[j//2] for j in range(2*nbs+1)]
    out=[]
    for i,(bc,rb) in enumerate(bands):
        out.append(zrow())
        out.append(brow(bc))
    out.append(zrow())
    return out
